from typing import Tuple, Dict
from collections import defaultdict

def solve_math_problem(roots: Tuple[int, ...], power: int, target_sum_indices: int) -> int:
    """
    Calculates the sum of coefficients a_k for specified even indices k 
    in the polynomial expansion of product((x + r)^power for r in roots).
    """
    if not roots or power < 0:
        raise ValueError("Roots must be non-empty and power must be non-negative.")

    # Polynomial represented as a dictionary {exponent: coefficient}
    # Start with P(x) = 1
    poly: Dict[int, int] = {0: 1}

    for root in roots:
        # Multiply current poly by (x + root)^power
        # (x + root)^power = sum_{i=0}^power C(power, i) * x^i * root^(power-i)
        factor_poly: Dict[int, int] = {}
        for i in range(power + 1):
            coeff = combinations(power, i) * (root ** (power - i))
            factor_poly[i] = coeff

        new_poly: Dict[int, int] = defaultdict(int)
        for exp1, coeff1 in poly.items():
            for exp2, coeff2 in factor_poly.items():
                new_poly[exp1 + exp2] += coeff1 * coeff2
        poly = dict(new_poly)

    # Sum coefficients for even indices up to target_sum_indices
    total_sum = 0
    for k in range(0, target_sum_indices + 1, 2):
        total_sum += poly.get(k, 0)

    return total_sum

def combinations(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    num = 1
    for i in range(k):
        num = num * (n - i) // (i + 1)
    return num
